select count(1)
from z000_mm_pur_store_item
where order_no = #{orderNo}
  and order_item_no = #{orderItemNo}

select coalesce(sum(i.quantity), 0)
from z000_mm_pur_store_item i
         inner join z000_mm_pur_store_header h on h.store_id = i.store_id
where i.order_no = #{orderNo}
  and i.order_item_no = #{orderItemNo}
  and h.buss_status != 'E'

select distinct store_id
from z000_mm_pur_store_item
where ref_buss_doc_id = #{refBussDocId}
  and ref_bstp = #{refBstp}

select count(distinct i.store_id)
from z000_mm_pur_store_item i
inner join z000_mm_pur_store_header h on i.store_id = h.store_id
where i.ref_buss_doc_id = #{refBussDocId}
  and i.ref_bstp = #{refBstp}


        and h.buss_status != 'E'


        and h.buss_status = #{bussStatus}

